// Get names of active non-GM users
const activePlayers = game.users.filter(u => u.active && u.isGM).map(u => u.name);

if (activePlayers.length === 0) {
    return ui.notifications.warn("No players are currently connected!");
}

// Shuffle the array (Fisher-Yates algorithm)
for (let i = activePlayers.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [activePlayers[i], activePlayers[j]] = [activePlayers[j], activePlayers[i]];
}

// Post to chat
ChatMessage.create({
    content: `
    <h4>Random Player Order:</h4>
    <ol>
      ${
        activePlayers.
          map(player => `<li>${player}</li>`)
          .join('\n')
      }
    </ol>
    `
});
